import sys

def solve_normal(n, a):
    """
    This is the normal solution approach:
    For this problem, we need to find the optimal order to remove elements.
    Key insight: For n elements, we do n-1 removals (keep 2 elements).
    We use dynamic programming where dp[i][j] represents the max points
    obtained when reducing subarray from index i to j to a single element.
    """
    n = len(a)

    if n <= 2:
        return 0

    # dp[i][j] = max points to reduce range [i,j] to a single element
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n):  # length is the number of elements in the range
        for i in range(n - length + 1):
            j = i + length
            dp[i][j] = -float('inf')
            for k in range(i + 1, j):
                # remove k last in range [i,j], getting points min(a[i], a[j])
                points = dp[i][k] + dp[k][j] + min(a[i], a[j])
                dp[i][j] = max(dp[i][j], points)

    result = 0
    for i in range(n - 1):
        result = max(result, dp[i][n-1] if i < n - 1 else 0)

    return result

