def solution(input_str):
    parts = input_str.strip().split()
    maxx = int(parts[0])
    maxy = int(parts[1])
    w = int(parts[2])

    # Dictionary mapping ratio (a, rev(a)) -> count of numbers with this ratio
    ratios = {}

    for i in range(1, maxx * maxy + 1):
        # We need to consider all a from 1 to maxx and b from 1 to maxy
        r = rev(i)
        # Store as tuple (i, r) to avoid floating point issues
        if (i, r) not in ratios:
            ratios[(i, r)] = 0
        ratios[(i, r)] += 1

    # Precompute prefix sums of ratios for each a in [1, maxx]
    revs_a = {}
    for i in range(1, maxx + 1):
        r = rev(i)
        revs_a[i] = (i, r)

    revs_b = {}
    for i in range(1, maxy + 1):
        r = rev(i)
        revs_b[i] = (i, r)

    # Group numbers by their key (a, rev(a))
    key_counts = {}
    for i in range(1, maxx + 1):
        key = (i, rev(i))
        if key not in key_counts:
            key_counts[key] = 0
        key_counts[key] += 1

    # Similarly for b
    key_counts_b = {}
    for i in range(1, maxy + 1):
        key = (i, rev(i))
        if key not in key_counts_b:
            key_counts_b[key] = 0
        key_counts_b[key] += 1

    # Find common keys (ratios that appear in both A and B)
    common = set(key_counts.keys()) & set(key_counts_b.keys())

    # For each x and y, count lucky tickets
    # A lucky ticket is (a, b) where (a, rev(a)) == (b, rev(b))
    total_max = 0
    min_xy = -1

    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            count = 0
            for key in common:
                count += key_counts[key] * key_counts_b[key]

            if count >= w:
                total = x * y
                if min_xy == -1 or total < total_max:
                    total_max = total
                    min_xy = (x, y)

    if min_xy != -1:
        return f"{min_xy[0]} {min_xy[1]}\n"
    else:
        return "-1\n"
