def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    frogs = []
    for i in range(1, n + 1):
        p, a = map(int, lines[i].split())
        frogs.append({'id': i, 'pos': p, 'a': a, 'alive': True})

    # Active frogs generate events for their next jumps
    events = []  # (pos, move_distance) for frogs

    # Track which rounds are done
    active_frogs = [(i, frogs[i-1]) for i in range(n) if frogs[i]['alive']]

    # For simulation, we'll simulate rounds until no moves remain
    # Each round: each active frog makes one jump

    def get_frogs_on_path(start_pos, length):
        """Get all frogs in the path from start_pos moving length cells forward"""
        result = set()
        # Path covers [start_pos, start_pos + length - 1] mod m (all inclusive)
        length = length % m
        if length == 0:
            return set()

        start = (start_pos % m)
        end = (start + length - 1) % m

        # Check if wrap-around
        if start <= end:
            for f in frogs:
                if f['alive'] and start <= f['pos'] <= end:
                    result.add(f['pos'])
        else:
            for f in frogs:
                if f['alive'] and (f['pos'] <= end or f['pos'] >= start):
                    result.add(f['pos'])

        return result

    # Create temporary positions after removal
    eliminated_count = 0
    elim_pos_set = set()

    # Simulate multiple rounds
    while active_frogs:
        elimination_events = []
        continue_round = False

        for i, frog in enumerate(active_frogs):
            frog_idx = frog - 1

            if frog_idx >= len(frogs):
                continue

            if not frogs[frog_idx]['alive']:
                continue

            if frogs[frog_idx]['a'] <= 0:
                continue

            frog = frogs[frog_idx]

            # Calculate new position
            frog['pos'] = (frog['pos'] + frog['a'] - 1) % m + 1
            if frog['pos'] > m:
                frog['pos'] -= m

            # Update position tracking
            frog_idx_next = -1
            for j, f in enumerate(frogs):
                if f['id'] == frog['id'] and f['alive']:
                    frog_idx_next = j
                    break

            # Mark all frogs in path as eliminated
            path_frogs = get_frogs_on_path(frog['pos'], frog['a'])
            for pos in path_frogs:
                for j, f in enumerate(frogs):
                    if f['alive'] and f['pos'] == pos:
                        f['alive'] = False
                        if 'next_jump' in dir(frog):
                            del frog['next_jump']

            frog_idx_no_kill = -1
            for j, f in enumerate(frogs):
                if f['id'] == frog['id'] and f['alive']:
                    frog_idx_no_kill = j
                    break

            # Decrease a value by how many frogs were knocked out
            killed = len(path_frogs)
            frog['a'] -= killed
            if frog['a'] <= 0 and frog_idx_no_kill >= 0:
                frogs[frog_idx_no_kill]['alive'] = False

        # Clean up completed frogs
        active_frogs = [(i, frogs[i-1]) for i in range(n) if frogs[i-1]['alive']]

        if not active_frogs:
            break
    ```

