MOD = 1000000007

def mat_mul(A, B, m):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k]:
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % m
    return C

def mat_pow(A, p, m):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while p > 0:
        if p & 1:
            result = mat_mul(result, base, m)
        base = mat_mul(base, base, m)
        p >>= 1
    return result

