# Your solution code here
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n = int(lines[0])
    if n < 3:
        return '0\n'

    coords = []
    for i in range(1, n + 1):
        line = lines[i].strip()
        if not line:
            coords.append((0, 0))
        else:
            parts = line.split()
            if len(parts) >= 2:
                x = int(parts[0])
                y = int(parts[1])
                coords.append((x, y))
            else:
                coords.append((0, 0))

    MOD = 1000000007

    # dp[i][j] = number of ways to triangulate subpolygon from vertex i to vertex j
    dp = [[0] * n for _ in range(n)]

    # Base case: adjacent vertices have 1 way (no triangles needed, just the edge)
    for i in range(n):
        dp[i][(i + 1) % n] = 1

    # Convert to linear indices for easier handling
    # dp[i][j] where i < j represents vertices i through j
    linear_dp = [[0] * n for _ in range(n)]

    for length in range(2, n):  # Number of edges in subpolygon minus 1
        for i in range(n - length + 1):
            j = i + length
            # Number of vertices from i to j is (j - i + 1)
            # Need at least 3 vertices to form a triangle
            if j - i < 2:
                linear_dp[i][j] = 1
                continue

            for k in range(i + 1, j):
                # Triangle vertices: i, k, j
                # Compute area (should be non-zero)
                xi, yi = coords[i]
                xk, yk = coords[k]
                xj, yj = coords[j]

                # Using shoelace formula for area (doubled, to avoid floats)
                area = abs(xi * (yk - yj) + xk * (yj - yi) + xj * (yi - yk))

                if area == 0:
                    continue

                # Check if diagonals (i,k) and (k,j) are valid (don't cross polygon edges)
                valid = True

                for edge_idx in range(n):
                    u, v = edge_idx, (edge_idx + 1) % n
                    Xu, Yu = coords[u]
                    Xv, Yv = coords[v]

                    # Skip edges that share vertices with the triangle
                    if u in [i, k, j] or v in [i, k, j]:
                        continue

                    # Check if diagonal (i, k) crosses edge (u, v)
                    xi_k = lambda x: coords[x]
                    def cross_product(a, b, c):
                        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

                    # Check diagonal (i, k) vs edge (u, v)
                    cp1 = cross_product(xi_k(i), xi_k(k), (Xu, Yu))
                    cp2 = cross_product(xi_k(i), xi_k(k), (Xv, Yv))
                    cp3 = cross_product((Xu, Yu), (Xv, Yv), xi_k(i))
                    cp4 = cross_product((Xu, Yu), (Xv, Yv), xi_k(k))

                    if ((cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0)) and \
                       ((cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0)):
                        valid = False
                        break

                    # Check diagonal (k, j) vs edge (u, v)
                    cp1_k = cross_product(xi_k(k), xi_k(j), (Xu, Yu))
                    cp2_k = cross_product(xi_k(k), xi_k(j), (Xv, Yv))
                    cp3_k = cross_product((Xu, Yu), (Xv, Yv), xi_k(k))
                    cp4_k = cross_product((Xu, Yu), (Xv, Yv), xi_k(j))

                    if ((cp1_k > 0 and cp2_k < 0) or (cp1_k < 0 and cp2_k > 0)) and \
                       ((cp3_k > 0 and cp4_k < 0) or (cp3_k < 0 and cp4_k > 0)):
                        valid = False
                        break

                if valid and linear_dp[i][k] and linear_dp[k][j]:
                    linear_dp[i][j] = (linear_dp[i][j] + linear_dp[i][k] * linear_dp[k][j]) % MOD

    return str(linear_dp[0][n - 1]) + '\n'
