The key challenge is efficient range concatenation - we can't literally concatenate all numbers for ranges like 1234-5678 (over 4000 numbers).

```python
import sys
sys.setrecursionlimit(300000)

MOD = 10**9 + 7

def get_digit_count(n):
    if n == 0:
        return 1
    return len(str(n))

def mod_pow(base, exp):
    return pow(base, exp, MOD)

def concat_range(n1, n2):
    """Concatenate all integers from n1 to n2 (inclusive) modulo MOD"""
    if n1 > n2:
        return 0

    start_digits = get_digit_count(n1)
    part_start = range(n1, n2 + 1)

    result = 0
    for num in part_start:
        digits_per_num = get_digit_count(num)
        result = (result * mod_pow(10, digits_per_num) + num) % MOD

    return result

class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        """Expression ::= Term { '+' Term }"""
        result = self.parse_term()

        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            term_val = self.parse_term()
            # Concatenate: result = result concatenated with term_val
            digits = get_digit_count(term_val)
            result = (result * mod_pow(10, digits) + term_val) % MOD

        return result

    def parse_term(self):
        """Term ::= Number | Number '-' Number | Number '(' Expression ')'"""

        # First get the count/number at the start
        count_start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        count = int(self.s[count_start:self.pos])

        # Check what comes next
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            # Pattern: count(expr) - repetition
            self.pos += 1  # skip '('
            expr_val = self.parse_expression()
            self.pos += 1  # skip ')'

            # Repeat expr_val, count times
            if count == 0:
                return 0

            if count == 1:
                return expr_val

            result = expr_val
            # Multiply by 10^len(expr) and add expr_val, count-1 times
            expr_val_digits = get_digit_count(expr_val)
            ten_pow = mod_pow(10, expr_val_digits)

            for _ in range(count - 1):
                result = (result * ten_pow + expr_val) % MOD

            return result

        else:
            # Pattern: Number '-' Number (range concatenation)
            if self.pos < len(self.s) and self.s[self.pos] == '-':
                self.pos += 1  # skip '-'
                end_num = 0
                while self.pos < len(self.s) and self.s[self.pos].isdigit():
                    self.pos += 1
                end_num = int(self.s[count_start:self.pos])

                # Concatenate range
                return concat_range(count, end_num)

            else:
                # Just a number
                while self.pos < len(self.s) and self.s[self.pos].isdigit():
                    self.pos += 1
                return int(self.s[count_start:self.pos]) % MOD

def solution(s):
    s = s.strip()
    if not s:
        return "0\n"

    parser = Parser(s)
    result = parser.parse()

    return str(result) + "\n"

# Verify with test cases
if __name__ == "__main__":
    print(solution('8-11\n'))  # Expected: 891011\n
    print(solution('2(2-4+1)+2(2(17))\n'))  # Expected: 100783079\n
    print(solution('1234-5678\n'))  # Expected: 745428774\n
```

