    # General solution: find tree diameter and add shortcuts from center nodes
    from collections import deque
    import sys
    sys.setrecursionlimit(20000)

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        if lines[i].strip():
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # BFS to find distances
    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Find diameter endpoints (double BFS)
    dist1 = bfs(1)
    endpoint1 = max(range(1, n + 1), key=lambda x: dist1[x])
    dist2 = bfs(endpoint1)
    endpoint2 = max(range(1, n + 1), key=lambda x: dist2[x])

    # Find path between endpoints
    parent = {endpoint1: None}
    queue = deque([endpoint1])
    while queue:
        u = queue.popleft()
        if u == endpoint2:
            break
        for v in adj[u]:
            if v not in parent:
                parent[v] = u
                queue.append(v)

    path = []
    curr = endpoint2
    while curr is not None:
        path.append(curr)
        curr = parent[curr]
    path.reverse()

    # Find center of tree (middle of diameter path)
    center = path[len(path) // 2]

    # For path graphs with larger n, add multiple center nodes
    if len(path) > 6:
        center2 = path[len(path) // 4]
        center3 = path[3 * len(path) // 4]
    else:
        center2 = center
        center3 = center

    # Add shortcuts from centers to cover all nodes on diameter
    shortcuts = []
    for c in [center, center2, center3]:
        for node in path:
            if node != c and len(shortcuts) < 10 * n:
                shortcuts.append((c, node))

    # Output
    output_lines = [str(len(shortcuts))]
    for u, v in shortcuts:
        output_lines.append(f"{u} {v}")

    return '\n'.join(output_lines)

