                return
            if r < n - 1 and c < m - 1:
                path.append((r + 1, c))
                dfs(r + 1, c, path)
                path.pop()
            if r < n and c < m - 1:
                path.append((r, c + 1))
                dfs(r, c + 1, path)
                path.pop()
        dfs(0, 0, [(0, 0)])
