def solution(input_str):
    # Parse input
    lines = input_str.strip('\n').split('\n')
    n, m, k = map(int, lines[0].split())

    # Parse priorities and sort cells
    priorities = []
    for i in range(n):
        priorities_line = lines[i+1]
        row_vals = priorities_line.split()
        for j, val in enumerate(row_vals):
            priorities.append((int(val), i, j))

    priorities.sort()
    sorted_cells = [(r, c) for (val, r, c) in priorities]

    # Precompute all monotonic paths
    def compute_all_paths():
        paths = []
        def dfs(r, c, curr_path):
            if r == n - 1 and c == m - 1:
                paths.append(tuple(curr_path))
                return
            if r < n - 1:
                curr_path.append((r + 1, c))
                dfs(r + 1, c, curr_path)
                curr_path.pop()
            if c < m - 1:
                curr_path.append((r, c + 1))
                dfs(r, c + 1, curr_path)
                curr_path.pop()
        dfs(0, 0, [(0, 0)])
        return paths

    all_paths = compute_all_paths()

    def is_correct_array(arr):
        for path in all_paths:
            bal = 0
            for r, c in path:
                if arr[r][c] == '(':
                    bal += 1
                else:
                    bal -= 1
                if bal < 0:
                    return False
            if bal != 0:
                return False
        return True

    # Backtracking to find k-th valid array
    assignment = [[''] * m for _ in range(n)]
    result = None
    count = 0

    def check_valid():
        nonlocal count
        if count < k:
            return False
        if result is None and is_correct_array(assignment):
            return True
        return False

    def solve(idx):
        global result
        if result is not None:
            return

        if idx == n * m:
            if is_correct_array(assignment):
                count += 1
                if count == k:
                    result = [row[:] for row in assignment]
            return

        r, c = sorted_cells[idx]

        # Try in priority order: '(' then ')'
        assignment[r][c] = '('
        solve(idx + 1)
        if result is not None:
            return
        assignment[r][c] = ')'
        solve(idx + 1)

    solve(0)

    output = '\n'.join(''.join(row) for row in result) if result else ''
    return output
