        configs_to_try = [(0, 0), (1, 0), (0, 1), (1, 1)]

    for sLR, sUD in configs_to_try:
        path = find_path(start, finish, n, m, board, sLR, sUD)
        if path:
            return path

    return ""


def find_path(start, finish, n, m, board, swapLR, swapUD):
    """Find path using BFS with specific swap configuration"""
    move_map = {
        'L': (0, -1 if not swapLR else 1),
        'R': (0, 1 if not swapLR else -1),
        'U': (-1 if not swapUD else 1, 0),
        'D': (1 if not swapUD else -1, 0),
    }

    queue = deque([(start, "")])
    visited = set([start])

    while queue:
        (r, c), moves = queue.popleft()

        if (r, c) == finish:
            return moves

        for move, (dr, dc) in move_map.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if board[nr][nc] != '*' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), moves + move + '\n'))

    return None
