from collections import deque

def solution(input_data):
    """Solve Vladik's game interactive problem"""
    lines = input_data.strip().split('\n')

    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    swapLR = int(parts[2]) if len(parts) >= 4 else 0
    swapUD = int(parts[3]) if len(parts) >= 4 else 0

    board = lines[1:n+1]

    # Find finish position (convert to 0-indexed)
    finish = None
    for r in range(n):
        for c in range(m):
            if board[r][c] == 'F':
                finish = (r, c)

    # BFS function with swap configuration
    def bfs(lr_swapped, ud_swapped):
        # Direction deltas based on swaps
        directions = {
            'U': (1 if ud_swapped else -1, 0),
            'D': (-1 if ud_swapped else 1, 0),
            'L': (0, 1 if lr_swapped else -1),
            'R': (0, -1 if lr_swapped else 1),
        }

        queue = deque([(0, 0, "")])
        visited = {(0, 0)}

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == finish:
                return path

            for direction in ["L", "R", "U", "D"]:
                dr, dc = directions[direction]
                nr, nc = r + dr, c + dc

                if 0 <= nr < n and 0 <= nc < m:
                    if board[nr][nc] != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc, path + direction + '\n'))

        return None

    # Try all swap configurations
    for sLR in [0, 1]:
        for sUD in [0, 1]:
            result = bfs(sLR, sUD)
            if result:
                return result

    return ""
